(22, 1, 'شقه عبد المنعم رياض', '1- غير مسجله شهر عقاري -لها حصه بالارض \r\n2- عداد كهرباء قديم - غاز طبيعي', '٢٢ شارع عبد المنعم رياض', 220.00, 3, 'available', 'Resale', '2025-09-10 13:15:28', 7, '3 غرف + 3 حمام', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'عبد المنعم رياض', 'الجيزة', '', NULL, '0', '5', NULL, NULL, 8000000.00, NULL, NULL, NULL, NULL, NULL, NULL, 'بواب', 'وسام', '01146086060', '', '', '', '', 0, 30.03459740, 31.19459440, 3, 0, NULL, 18, 'EGP'),
