(83, 1, 'شقه ميدان فيني', '1- الشقه حبري وتري النيل من الجانب \r\n2-البيع شامل العفش والاجهزه \r\n3-العقار مسجل و واخده حاليا رقم التسجيل وتم رفع المساحه العسكريه وقربت تتسجل  لكنها في حكم المسجل \r\n4- لها حصه بالارض', '7 شارع فيني السد العالي امام فندق شيرتون', 150.00, 2, 'available', 'Resale', '2025-09-15 14:20:57', 7, '2 غرف + 2حمام + 2 بلكونه', 5, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'ميدان فيني', 'الجيزة', '', 20, '2003', '11', NULL, NULL, 5500000.00, NULL, NULL, NULL, NULL, NULL, NULL, 'وكيل', 'ياسر', '01062007918', '', '', '', '', 1, 30.03905730, 31.21994320, 2, 2, NULL, 78, 'EGP'),
(84, 1, 'دوبلكس شارع التحرير', '1-الدور 18 و19 وفوقيهم غرفه الخدمات \r\n2-تري النيل بوضوح الفيو من الشقه علي النيل من جميع الجهات \r\n3- مسجله شهر عقاري ولها حصه بالارض', '131عماره بنك الاسكندريه امام كشري التحرير شارع التحرير الدقي', 300.00, 4, 'available', 'Resale', '2025-09-15 14:32:53', 7, '4 غرف + 3حمام', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'شارع التحرير', 'الجيزة', '', 19, '2001', '19', NULL, NULL, 11000000.00, NULL, NULL, NULL, NULL, NULL, NULL, 'وكيل', 'ياسر', '10622007918', '', '', '', '', 0, 30.03908010, 31.22766810, 3, 0, NULL, 79, 'EGP'),
(85, 1, 'شقه  دور ارضي بجاردن', '1-تصلح تجاري \r\n2-لها حصه بالارض 58 متر \r\n3-والأرقام التواصل  01001855252 -01001621333 -01145669958', '121 شارع السودان', 185.00, 4, 'available', 'Resale', '2025-09-15 15:05:49', 7, '4 غرف + 2 حمام +تراس', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'السودان', 'الجيزة', '', 5, 'تسعينات', 'ارضي بجاردن', NULL, NULL, 3800000.00, NULL, NULL, NULL, NULL, NULL, NULL, 'مالك', 'سيف الدين ايهاب', '01001855252', '', '', '', '', 0, 30.03746230, 31.19948240, 2, 1, NULL, 80, 'EGP'),
