(280, 1, 'شارع الا خليفة', 'البرج تحت الانشاء \r\nالدور علي شقتين \r\nاسانسير واحد \r\nعداد الكهرباء متاح \r\nعداد المياه متاح \r\nمش متاح غاز ولكن السكان بيقدموا عليه \r\nمش مسجله شهر عقاري ولكن الارض تسلسل ملكية وشغال في اوراق صحة التوقيع مع الشريك اللي معاه\r\nله حصة في الارض \r\nالاستلام في خلال شهرين للادوار الاولي الي 4 شهور للادوار العاليه \r\nالادوار المتاحة تاني بلكونه والخامس ومن الدور السابع الي الدور 12 \r\nالعمولة 2.5%', 'شارع الاخليفة متفرع من ميدان الساعه - فيصل', 130.00, 3, 'available', 'Resale', '2025-11-11 15:19:42', 10, '3 غرف + 2 حمام', 1, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'فيصل', 'الجيزة', '', 12, '', '5 - 7 - 8 - 9 - 10 - 11 - 12', NULL, 25.00, 1100000.00, 1200000.00, NULL, NULL, NULL, NULL, NULL, 'مالك', 'محمد', '01144309869', '', '', '', '', 0, 30.00140750, 31.15002550, 2, 0, NULL, 271, 'EGP'),
(281, 1, 'شارع عمار بن ياسر', 'عداد كهرباء كارت \r\nعداد مياه \r\nتوصيلة الغاز واصله لغيت باب الشقة \r\nالدور علي 3 شقق \r\nاسانسر واحد\r\nمش مسجلة شهر عقاري ومفيش صحة توقيع ولكن له حصة في الارض \r\nعمولة 1.5%', '49 شارع عمار بن ياسر - فيصل', 140.00, 3, 'available', 'Resale', '2025-11-13 11:44:15', 10, '3 غرف + 2 حمام', 5, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'فيصل', 'الجيزة', '', 13, '', '5', NULL, NULL, 1600000.00, NULL, NULL, NULL, NULL, NULL, NULL, 'مالك', 'حماده', '01157170733', '', '', '', '', 2, 29.99289790, 31.20761690, 2, 0, NULL, 272, 'EGP'),
