(422, 1, 'شارع السودان', 'شبكة كبلات كهرباء جديدة بالكامل \r\nغاز طبيعي \r\nمسجلة شهر عقاري \r\nله حصة في الارض', 'شارع السودان', NULL, 3, 'available', 'Resale', '2025-12-10 12:08:21', 10, '3 غرف + 2 حمام', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'المهندسين', 'الجيزة', '', 16, '', '11', 160.00, NULL, 3100000.00, NULL, NULL, NULL, NULL, NULL, NULL, 'مالك', 'امير', '+201002334441', '', NULL, '', NULL, 0, 30.04461100, 31.19653400, 2, NULL, 2, 398, 'EGP'),
