(424, 1, 'ميدان لبنان', 'الدور علي شقتين \r\nمعاها باكية جراج خاصة مغلقة بباب خارجي \r\nمسجلة شهر عقاري \r\nعقد اخضر \r\nعداد غاز', 'ميدان لبنان', 200.00, 3, 'available', 'Resale', '2025-12-10 13:07:25', 10, '3 غرف + 2 حمام', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'المهندسين', 'الجيزة', '', 12, 'تسعينات', '9', NULL, NULL, 6500000.00, NULL, NULL, NULL, NULL, NULL, NULL, 'مالك', 'الهام', '+201284429179', '', NULL, '', NULL, 0, 30.05733000, 31.19853800, 2, NULL, NULL, 400, 'EGP'),
(425, 1, 'شارع حسب الله', 'له حصة في الارض \r\nالارضيات سيراميك \r\nالنوافد pvc تركي مانع الصوت والحرارة \r\nوالزجاج فاميه مرايا عاكس', 'شارع حسب الله - الملك الصالح', 145.00, 3, 'available', 'Resale', '2025-12-10 13:19:34', 10, '3 غرف + حمام', 5, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'مصر القديمة', 'القاهرة', '', 11, '', '9', NULL, NULL, 3500000.00, NULL, NULL, NULL, NULL, NULL, NULL, 'مالك', 'عمر', '+201200999105', '', NULL, '', NULL, 0, 30.01415000, 31.23229300, 1, NULL, 2, 401, 'EGP'),
(426, 1, 'شارع النفراوي', 'رخصة \r\nفيها مياه \r\nعداد كهرباء \r\nمدخل رخام \r\nاول ساكن \r\nالسعر قابل للتفاوض', '3 شارع النفراوي بجوار مستشفي السنابل متفرع من شارع مصر والسودان وعشر دقائق مشي لمترو منشية الصدر او مترو الدمرداش', 80.00, 2, 'available', 'Resale', '2025-12-10 13:29:49', 10, 'غرفتين وحمام', 5, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'حدائق القبه', 'القاهرة', '', 12, '2023', '3', NULL, NULL, 1300000.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'فام موسي', '+201225090790', '', NULL, '', NULL, 0, 30.08497700, 31.28187400, 1, NULL, 1, 402, 'EGP'),
(427, 1, 'شارع المساكن الرئيسي', 'له حصة في الارض \r\nعداد كهرباء \r\nعداد غاز \r\nعداد مياه خاص \r\nماتور مياه خاص \r\nخط تليفون ارضي وانترنت \r\nارضيات الريسبشن والطر قة بورسلين جوهرة فرز اول \r\nارضيات الغرف سيراميك باركيه فرز اول \r\nاطقم صحية ديورافيت وخلاطات ايديال استاندر \r\nتاسيس كهرباء ممتاز وصلات تكييف ونت ودش داخلية موزعة علي الغرف \r\nسعر الايجار بالبرج 8000 جنيه \r\nلو مفروش بتوصل ل 20000 جنية \r\nالسعر غير شامل العفش \r\nالسعر قابل للتفاوض', 'شارع المساكن الرئيسي متفرع من العشرين', 165.00, 3, 'available', 'Resale', '2025-12-10 13:54:35', 10, '3 غرف + 2 حمام +بلكونه', 5, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'فيصل', 'الجيزة', '', 10, '', '2', NULL, NULL, 1500000.00, NULL, NULL, NULL, NULL, NULL, NULL, 'مالك', 'محمد', '+201003870835', '', NULL, '', NULL, 0, 30.01371200, 31.19474500, 2, 1, 1, 403, 'EGP'),
(428, 1, 'فيصل الرئيسي', 'الدور علي 4 شقق \r\nله حصة في الارض \r\nالسعر بدون العفش \r\nالسعر قابل التفاوض', 'اخر فيصل الرئيسي', NULL, 2, 'available', 'Resale', '2025-12-10 15:29:35', 10, 'غرفتين وحمام', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'فيصل', 'الجيزة', '', 11, 'تسعينات', '5', 120.00, NULL, 3000000.00, NULL, NULL, NULL, NULL, NULL, NULL, 'مالك', 'العميد علي', '+201115440755', '', NULL, '', NULL, 0, 29.99296300, 31.15356300, 1, NULL, 2, 404, 'EGP'),
(429, 1, 'كمبوند جنة', 'عداد كهرباء \r\nعداد غاز \r\nسلوك السويدي وحمامات ديورفيت سيراميك كليوباترا فرز اول \r\nفي امكانية الشراء بالعفش والبمطبخ ولكن بسعر منفصل \r\nله حصة في الارض \r\nمسجلة شهر عقاري \r\nالدور علي 6 شقق', 'كمبوند جنة بجوار كمبوند البستان والمستثمر الصغير', 154.00, 3, 'available', 'Resale', '2025-12-10 15:57:32', 10, '3 غرف + 2 حمام', 6, NULL, NULL, NULL, NULL, 'كمبوند جنة', NULL, NULL, NULL, 'المهندسين', 'الجيزة', '', 5, '', '2', NULL, NULL, 2550000.00, NULL, NULL, NULL, NULL, NULL, NULL, 'مالك', 'محمود', '+201127609760', '', NULL, '', NULL, 0, 29.94015900, 30.94276700, 2, 2, 1, 405, 'EGP'),
(430, 1, 'شارع المامون', 'الشقة كلها متركب فيها حديد وسلك للامن \r\nالارضيات بورسلين وسيراميك باركيه \r\nله حصة في الارض \r\nصحة وتوقيع وتوكيل \r\nاول مالك \r\nالدور علي شقتين \r\nالسعر بالعفش 3,200.000\r\nالسعر بدون العفش 3.100.000', '13 شارع المامون متفرع من شارع عبد المنعم سند', 135.00, 3, 'available', 'Resale', '2025-12-11 10:59:40', 10, '3 غرف + 2 حمام', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'المهندسين', 'الجيزة', '', 7, 'سبعينات', 'الارضي', NULL, NULL, 3200000.00, NULL, NULL, NULL, NULL, NULL, NULL, 'مالك', 'سهير', '+201005179592', '', NULL, '', NULL, 0, 30.06703700, 31.20642900, 2, 3, NULL, 406, 'EGP'),
(431, 1, 'شارع جامعة الدول العربية', 'تصلح مكتب او عيادة او مقر شركة \r\nباب شقة مصفح \r\nسلم العمارة رخام \r\nلا توجد مناور \r\nعداد كهرباء قديم \r\nعداد غاز قديم \r\nعداد مياه منفصل \r\nالدور علي شقتين \r\nمبني 90 تبع المحافظة والاسكان والتعمير', 'شارع جامعة الدول العربية مباشرة', 75.00, 2, 'available', 'Resale', '2025-12-11 11:26:59', 10, 'غرفتين وحمام', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'المهندسين', 'الجيزة', '', 5, '', '3', NULL, NULL, 2000000.00, NULL, NULL, NULL, NULL, NULL, NULL, 'مالك', 'علي', '+201553422107', '', NULL, '', NULL, 0, 30.05213400, 31.20346500, 1, 2, NULL, 407, 'EGP'),
