(594, 1, 'الحي الثالث', 'ادوار متكررة \r\nعمارة شيك مدخل رخام \r\nالمشتري اول توكيل من صاحب العمارة \r\n3 عدادات كهرباء زغاز ومياه', 'الحي الثالث - المجاورة الثالثة - قريبه لجميع الخدمات والمدارس وخطوات لشارع الرنامول وللمحورين ودقائق من جامعة اكتوبر الحصري', 220.00, 3, 'available', 'Resale', '2025-12-27 12:53:39', 10, '3 غرف +3 حمام', 6, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, '6 أكتوبر', 'الجيزة', '', NULL, '', '', NULL, NULL, 4500000.00, NULL, NULL, NULL, NULL, NULL, NULL, 'وسيط', 'عامر', '+201030966628', '', NULL, '', NULL, 0, 29.95832800, 30.97474300, 3, NULL, 1, 458, 'EGP'),
(595, 1, 'برج اسراء المعلمين', 'متاح دوار متكررة \r\nعداد كهرباء ومياه وغاز \r\nمسجله شهر عقاري \r\nله حصة في الارض \r\n240 متر متقسمه 3 غرف و3 حمام \r\n270 متر متقسمه 3 غرف و 3 حمام وليفينج', '20 شارع اسراء المعليمن متفرع من ميدان لبنان', NULL, 3, 'available', 'Resale', '2025-12-27 13:34:51', 10, '3 غرف +3 حمام', 1, NULL, NULL, NULL, NULL, '', 240.00, 270.00, NULL, 'المهندسين', 'الجيزة', '', 11, '', '', NULL, NULL, 7200000.00, NULL, NULL, NULL, NULL, 30000.00, NULL, 'مالك', 'ايمن', '+201025701701', '', NULL, '', NULL, 0, 30.06082000, 31.19453300, 3, NULL, 2, 459, 'EGP'),
(596, 4, '', 'الدور الارضي 40 متر والدور العلوي 410 متر \r\nمدخل المحل هو ممكن يبقي حق انتفاع من الجهاز وهو في حدود 100 متر \r\nالدور الارضي به قسم الكاشير والتيك واي وشوايه \r\nالدور العلوي فيه صالة \r\nالصالة من الوجهه حتي حمامات الجست واول قسم المطبخ \r\nقسم المطبخ كامل بالمعدات وشواية كبري مجهزه بالمدخنه لخدمة الصالة والوجبات بالاضافة الي قسم الاستيوار \r\nالبيع بالمعدات \r\nالسعر قابل للتفاوض في حالة الدفع كاش \r\nوفي حالة البيع بدون المعدات هيتم خصم حساب المعدات والتجهيزات \r\nفي حالة الايجار يكون ايجار لمطعم فقط والايجار بالمعدات والايجار 430 الف في الشهر وقابل للتفاوض', 'الحي الثالث علي المحور المركزي', 450.00, NULL, 'available', 'Resale', '2025-12-27 15:28:10', 10, '', 5, NULL, NULL, NULL, NULL, 'الحي الثالث', NULL, NULL, NULL, '6 أكتوبر', 'الجيزة', '', NULL, '', 'ارضي و اول', NULL, NULL, 65000000.00, NULL, NULL, NULL, NULL, NULL, NULL, 'مالك', 'الحاج حسين', '+201148889001', '', NULL, '', NULL, 0, 29.96158200, 30.92781300, NULL, NULL, NULL, 460, 'EGP'),
